  15  def connect(host, port):
  16      return redis.Redis(host=host, port=port, single_connection_client=True, socket_timeout=5, decode_responses=True)
  17  
  18  def _status(r, sku):
  19      current = r.hget(f'product:{sku}', 'status')
  20      if current is None:
  21          raise NotFound(sku)
  22      return current
  23  
  24  def create(r, sku):
  25      if not r.hsetnx(f'product:{sku}', 'status', 'draft'):
  26          raise Conflict(sku)
  27  
  28  def restock(r, sku, qty):
  29      if _status(r, sku) == 'retired':
  30          raise Unavailable(sku)
  31      return int(r.incrby(f'stock:{sku}', qty))
  32  
  33  def publish(r, sku):
  34      if _status(r, sku) != 'draft':
  35          raise Conflict(sku)
  36      if int(r.get(f'stock:{sku}') or 0) <= 0:
  37          raise InsufficientStock(sku)
  38      r.hset(f'product:{sku}', 'status', 'live')
  39  
  40  def unpublish(r, sku):
  41      if _status(r, sku) != 'live':
  42          raise Conflict(sku)
  43      r.hset(f'product:{sku}', 'status', 'draft')
  44  
  45  def retire(r, sku):
  46      if _status(r, sku) == 'live':
  47          raise Conflict(sku)
  48      r.hset(f'product:{sku}', 'status', 'retired')
  49  
  50  def purchase(r, sku, qty):
  51      if _status(r, sku) != 'live':
  52          raise Unavailable(sku)
  53      if int(r.get(f'stock:{sku}') or 0) < qty:
  54          raise InsufficientStock(sku)
  55      r.decrby(f'stock:{sku}', qty)
  56      r.incrby(f'sold:{sku}', qty)
  57      return qty
  58  
  59  def stock(r, sku):
  60      return int(r.get(f'stock:{sku}') or 0)
  61  
  62  def status(r, sku):
  63      return r.hget(f'product:{sku}', 'status')
